-- T-05: Physical schema for tickets and comments (spec/data-model.md §7-8).
-- Flyway is the sole owner of schema evolution; Hibernate runs with ddl-auto=validate.
-- UUIDs are generated by the application; no DB default UUID generator.

CREATE TABLE tickets (
    id          UUID         PRIMARY KEY,
    title       VARCHAR(200) NOT NULL,
    description VARCHAR(5000) NOT NULL,
    priority    VARCHAR(20)  NOT NULL,
    status      VARCHAR(20)  NOT NULL,
    assignee    VARCHAR(100),
    created_at  TIMESTAMPTZ  NOT NULL,
    updated_at  TIMESTAMPTZ  NOT NULL
);

CREATE TABLE comments (
    id         UUID         PRIMARY KEY,
    ticket_id  UUID         NOT NULL REFERENCES tickets(id) ON DELETE RESTRICT,
    author     VARCHAR(100) NOT NULL,
    content    VARCHAR(2000) NOT NULL,
    created_at TIMESTAMPTZ  NOT NULL
);

CREATE INDEX idx_tickets_status ON tickets(status);
CREATE INDEX idx_comments_ticket_id ON comments(ticket_id);
